mapper.select:
select a.*, u.nick_name nickName from (
select id, family_id, host_id, start_time, end_time, live_time_sec, ticket, times
from ${dbLive}.live_host_wage_day

    host_id = #{hostId}
    and start_time >= #{startTime}
    and end_time <= #{endTime}
) a
left join ${dbLive}.live_user u on a.host_id=u.id

select o.family_id familyId, f.name familyName, f.user_id familyUserId, f.nick_name familyNickName, SUM(o.live_time_sec) as alltime, sum(o.ticket) as allticket, SUBSTR(o.start_time,1,10) as shijian, #{countTime} timedata from ${dbLive}.live_host_wage_day o left join ${dbLive}.live_family f on o.family_id=f.id
and o.family_id = #{dto.familyId} and f.name like concat('%',#{dto.familyName},'%') and f.nick_name like concat('%',#{dto.familyNickName},'%') and o.start_time >= #{dto.startTime} and o.end_time <= #{dto.endTime}
group by o.family_id order by o.family_id asc
